import __main__
import logging
import splunk.entity as en
from splunk.util import normalizeBoolean

logger = logging.getLogger('splunk.appserver')

def _find_entry_in_list(entries, name):
    """
    Gets an entry from a list of entries for a given name.

    @type  entries: list(dict)
    @param entries: A list of entries.

    @type  name: string
    @param name: The entry name.

    @rtype: dict | None
    @return: The found entry, or None if not found.
    """
    for entry in entries:
        if entry['name'] == name:
            return entry
    return None

def _parse_response(data):
    """
    Parses data from a splunkd REST request for a specific stanza and sanitize
    the attributes.

    @type  data: Entity | EntityCollection
    @param data: The response data from a splunkd REST request.

    @rtype: dict | list(dict)
    @return: The sanitized attributes for a specific stanza.
    """
    entities = [data] if isinstance(data, en.Entity) else data.values()
    # map an entity object to an object of normalized attributes
    def normalize_attributes_pred(entity):
        excluded_attrs = ['disabled', 'eai:acl', 'eai:appName', 'eai:userName']
        normalized_attrs = { key: normalizeBoolean(value) for key, value in entity.iteritems() if key not in excluded_attrs }
        normalized_attrs['name'] = entity.name
        return normalized_attrs
    normalized_entries = list(map(normalize_attributes_pred, entities))
    # return dict if targetting specific stanza, otherwise return array
    return normalized_entries[0] if len(normalized_entries) == 1 and isinstance(data, en.Entity) else normalized_entries

def _make_get_request(url, stanza, app, owner, session_key, use_cached_entities):
    """
    Makes a GET request to a splunk endpoint.

    @type  url: string
    @param url: The splunkd URL for the .conf file which you are trying to fetch.

    @type  stanza: string | None
    @param stanza: The stanza within the .conf file which you are trying to fetch. Set as
                   None if you want all entries returned.

    @type  app: string
    @param app: The app namespace for the request.

    @type  owner: string
    @param owner: The owner namespace for the request.

    @type  session_key: string
    @param session_key: A key which is used to authenticate REST requests.

    @type  use_cached_entities: bool
    @param use_cached_entities: Whether or not to use cached entities. Note that cached.py
                                relies on cherrypy and creates a background thread to cleanup
                                cached calls. Conseqeuntly, do not use caching when not in the
                                context of cherrypy.

    @rtype data: Entity | EntityCollection
    @return: The response data from a splunkd REST request.
    """
    if use_cached_entities:
        from splunk.appserver.mrsparkle.lib import cached
        entity_module = cached
    else:
        entity_module = en
    if stanza is not None:
        return entity_module.getEntity(
            url,
            stanza,
            namespace=app,
            owner=owner,
            sessionKey=session_key
        )
    return entity_module.getEntities(
        url,
        namespace=app,
        owner=owner,
        sessionKey=session_key
    )

def _get_settings(url, stanza=None, failure_message='Failed to get setting', app='system', owner='nobody', session_key=None):
    """
    A generic function which gets and normalizes settings associated with a specific .conf file.

    @type  url: string
    @param url: The splunkd URL for the .conf file which you are trying to fetch.
                The URL must request a JSON response to parse properly (ie. 'output_mode=json').

    @type  stanza: string | None
    @param stanza: The stanza within the .conf file which you are trying to fetch. Set as
                   None if you want all entries returned.

    @type  failure_message: string
    @param failure_message: The message you would like to log in the case of failure.

    @type  app: string
    @param app: The app namespace for the request.

    @type  owner: string
    @param owner: The owner namespace for the request.

    @type  session_key: string
    @param session_key: A key which is used to authenticate REST requests.

    @rtype: list | dict | None
    @return: The resolved settings. A dict if a valid stanza was specified. A list
             if no stanza was specified or an empty list if no stanza was found. None
             is returned if the request failed.
    """
    try:
        if hasattr(__main__, 'IS_CHERRYPY'):
            import cherrypy
            _session_key = cherrypy.session.get('sessionKey')
            use_cached_entities = True
        else:
            _session_key = session_key
            use_cached_entities = False
        data = _make_get_request(url, stanza, app, owner, _session_key, use_cached_entities)
        return _parse_response(data)
    except Exception as e:
        logger.warning('{}: {}'.format(failure_message, str(e)))
    return None

def _get_web_feature(session_key, feature_name, failure_message):
    settings = _get_settings('web-features', failure_message=failure_message, session_key=session_key)
    return _find_entry_in_list(settings, feature_name)

def get_dashboards_csp_settings(session_key=None):
    return _get_web_feature(session_key, 'feature:dashboards_csp', 'Failed to get dashboards csp settings')

def get_highcharts_accessibility_settings(session_key=None):
    return _get_web_feature(session_key, 'feature:highcharts_accessibility', 'Failed to get highcharts accessibility settings')

def get_manager_xml_pages_settings(session_key=None):
    return _get_web_feature(session_key, 'feature:manager_xml_pages', 'Failed to get Manager XML pages settings')

# cache this setting specifically until splunk restart
web_features_page_migration_cache = None
def get_page_migration_settings(session_key=None):
    global web_features_page_migration_cache
    if web_features_page_migration_cache:
        return web_features_page_migration_cache
    web_features_page_migration_cache = _get_web_feature(session_key, 'feature:page_migration', 'Failed to get page migration settings with status code {}')
    return web_features_page_migration_cache

def shouldDisplayV2Page(feature_flag):
    web_feature_flags = get_page_migration_settings()
    if feature_flag in web_feature_flags:
        return normalizeBoolean(web_feature_flags[feature_flag])
    return False

# returns settings under [feature:feature_name] stanza in the web-features.conf 
# or None if not present
def _get_settings_for_feature(feature_name, session_key=None):
    return _get_web_feature(session_key, f'feature:{feature_name}', f'Failed to get {feature_name} settings')

# returns feature_flag value in the [feature:feature_name] stanza in the web-features.conf 
# or None if not present
def _get_setting_for_feature(feature_name, feature_flag, session_key=None):
    try:
        web_feature_flags = _get_settings_for_feature(feature_name, session_key)
        return web_feature_flags.get(feature_flag, None)
    except:
        return None

# checks if web-features.conf has feature_flag in the [feature:feature_name]
# and it is boolean-like and could be strictly normalized to True
def is_feature_enabled(feature_name, feature_flag, session_key=None):
    feature_flag = _get_setting_for_feature(feature_name, feature_flag, session_key)
    return feature_flag is not None and normalizeBoolean(feature_flag, True)

